#include "arduino_secrets.h"

const byte RED_A    = 11; 
const byte YELLOW_A = 12; 
const byte GREEN_A  = 13; 

const byte RED_B    = 8; 
const byte YELLOW_B = 9;  
const byte GREEN_B  = 10; 

const byte RED_C    = 7;  
const byte YELLOW_C = 6;  
const byte GREEN_C  = 5; 

const byte RED_D    = 4;  
const byte YELLOW_D = 3;  
const byte GREEN_D  = 2;  

void setup() {
  for (int pin = 2; pin <= 13; pin++) {
    pinMode(pin, OUTPUT);
  }

  setAllRed();
  delay(10);
}

void setAllRed() {
  digitalWrite(RED_A, HIGH);
  digitalWrite(RED_B, HIGH);
  digitalWrite(RED_C, HIGH);
  digitalWrite(RED_D, HIGH);

  digitalWrite(YELLOW_A, LOW); digitalWrite(GREEN_A, LOW);
  digitalWrite(YELLOW_B, LOW); digitalWrite(GREEN_B, LOW);
  digitalWrite(YELLOW_C, LOW); digitalWrite(GREEN_C, LOW);
  digitalWrite(YELLOW_D, LOW); digitalWrite(GREEN_D, LOW);
}

void loop() {

  setAllRed();
  digitalWrite(RED_A, LOW);
  digitalWrite(GREEN_A, HIGH);
  delay(1000);

  digitalWrite(GREEN_A, LOW);
  digitalWrite(YELLOW_A, HIGH);
  delay(500); 


  setAllRed();
  digitalWrite(RED_B, LOW);
  digitalWrite(GREEN_B, HIGH);
  delay(1000);

  digitalWrite(GREEN_B, LOW);
  digitalWrite(YELLOW_B, HIGH);
  delay(500);

  setAllRed();
  digitalWrite(RED_C, LOW);
  digitalWrite(GREEN_C, HIGH);
  delay(1000);

  digitalWrite(GREEN_C, LOW);
  digitalWrite(YELLOW_C, HIGH);
  delay(500);

  setAllRed();
  digitalWrite(RED_D, LOW);
  digitalWrite(GREEN_D, HIGH);
  delay(1000);

  digitalWrite(GREEN_D, LOW);
  digitalWrite(YELLOW_D, HIGH);
  delay(500);
}
